import { NextRequest, NextResponse } from 'next/server'
import { db } from '@/lib/db'
import { type Item } from '@/types'

export async function GET(req: NextRequest) {
  const id = new URL(req.nextUrl.href).searchParams.get('id')
  if (!id) return NextResponse.json({ error: 'no id in URL' }, { status: 400 })
  const row = await db.item.findFirst({ where: { id } })
  if (!row) return NextResponse.json({ error: 'item not found' }, { status: 404 })
  return NextResponse.json({ item: row })
}

export async function PUT(req: NextRequest) {
  const id = new URL(req.nextUrl.href).searchParams.get('id')
  if (!id) return NextResponse.json({ error: 'no id in URL' }, { status: 400 })
  const body = await req.json()
  const name = String(body.name ?? '').trim()
  if (!name || name.length > 60) {
    return NextResponse.json({ error: 'name is required (1-60 chars)' }, { status: 400 })
  }
  const age = Number(body.age)
  if (!Number.isInteger(age) || age < 0 || age > 40) {
    return NextResponse.json({ error: 'age must be an integer 0-40' }, { status: 400 })
  }
  const row = await db.item.update({
    where: { id },
    data: { name, species: String(body.species ?? 'dog').trim(), age },
  })
  return NextResponse.json({ item: row }, { status: 200 })
}

